from sqlalchemy import func, select
from sqlalchemy.orm import Session

from .models import User


def find_by_email(session: Session, email: str) -> User | None:
    stmt = select(User).where(User.email == email)
    return session.scalars(stmt).first()


def active_users(session: Session) -> list[User]:
    stmt = select(User).where(User.is_active).order_by(User.created_at)
    return list(session.execute(stmt))


def count_in_team(session: Session, team_id: int) -> int:
    stmt = select(func.count()).select_from(User).where(User.team_id == team_id)
    return session.scalar(stmt)
